 import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, CylinderGeometry, SphereGeometry, BoxGeometry } = THREE;

  const colors = config.intent?.visualSpec?.colors || config.colors || {};
  const ink = colors.ink || '#16161d';
  const paper = colors.paper || '#e8ecf2';
  const accent = colors.accent || '#ff2a38';
  const surface = colors.surface || '#0b0b10';

  const root = new Group();
  root.name = config.id || 'home-divider';
  root.userData.atlasRegion = { atlas: 0, rect: [0, 0, 512, 320] };

  const timelines = [];
  const disposables = [];

  function markDisposable(obj) {
    if (obj.geometry) disposables.push(obj.geometry);
    if (obj.material) disposables.push(obj.material);
  }

  function addDisposableGeometry(geo) {
    disposables.push(geo);
    return geo;
  }

  function addDisposableMaterial(mat) {
    disposables.push(mat);
    return mat;
  }

  // Local stage plane behind the rule
  const stageGeo = new PlaneGeometry(3.6, 0.75);
  addDisposableGeometry(stageGeo);
  const gradNode = mix(color(surface), color(ink), uv().y);
  const stageMat = new MeshBasicNodeMaterial({
    colorNode: gradNode,
    transparent: true,
    opacity: 0.9,
    side: THREE.DoubleSide,
  });
  addDisposableMaterial(stageMat);
  const stage = new Mesh(stageGeo, stageMat);
  stage.position.set(0, 0, -0.15);
  stage.name = 'divider-stage';
  root.add(stage);

  // Machined rule + center jewel fallback builder
  function buildFallback() {
    const ruleGeo = new CylinderGeometry(0.014, 0.014, 2.2, 32);
    addDisposableGeometry(ruleGeo);
    const ruleMat = new MeshStandardNodeMaterial({
      color: paper,
      metalness: 0.55,
      roughness: 0.5,
    });
    addDisposableMaterial(ruleMat);
    const rule = new Mesh(ruleGeo, ruleMat);
    rule.rotation.z = Math.PI / 2;
    rule.name = 'machined-rule';
    root.add(rule);

    const jewelGeo = new SphereGeometry(0.07, 32, 32);
    addDisposableGeometry(jewelGeo);
    const jewelMat = new MeshStandardNodeMaterial({
      color: accent,
      emissive: accent,
      emissiveIntensity: 1.8,
      metalness: 0.35,
      roughness: 0.25,
    });
    addDisposableMaterial(jewelMat);
    const jewel = new Mesh(jewelGeo, jewelMat);
    jewel.name = 'center-jewel';
    root.add(jewel);

    return { rule, jewel };
  }

  // Load the generated GLB
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      const model = gltf.scene || gltf;
      model.name = 'gltf-model';
      root.add(model);

      model.traverse((child) => {
        child.userData.isModelPart = true;
        if (child.isMesh) {
          child.castShadow = true;
          child.receiveShadow = true;
        }
      });
    }).catch(() => {
      buildFallback();
    });
  } else {
    buildFallback();
  }

  // Accent focus edge
  const edgeGeo = new PlaneGeometry(3.65, 0.8);
  addDisposableGeometry(edgeGeo);
  const edgeMat = new MeshBasicNodeMaterial({
    color: accent,
    transparent: true,
    opacity: 0,
    side: THREE.DoubleSide,
  });
  addDisposableMaterial(edgeMat);
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.position.set(0, 0, 0.02);
  edge.visible = false;
  edge.name = 'focus-edge';
  root.add(edge);

  // Confirm panel for trpc.visits.book.slot data binding
  const confirmPanel = new Group();
  confirmPanel.name = 'confirm-panel';
  confirmPanel.visible = false;
  confirmPanel.position.set(0, -0.6, 0.35);
  confirmPanel.scale.set(0, 0, 0);

  const panelGeo = new PlaneGeometry(1.6, 0.52);
  addDisposableGeometry(panelGeo);
  const panelMat = new MeshBasicNodeMaterial({ color: paper });
  addDisposableMaterial(panelMat);
  const panel = new Mesh(panelGeo, panelMat);
  confirmPanel.add(panel);

  const slotLabel = ctx.fontAtlas.createText('—', {
    fontSize: 0.12,
    color: surface,
    align: 'center',
  });
  slotLabel.position.set(0, 0.08, 0.02);
  confirmPanel.add(slotLabel);

  const statusLabel = ctx.fontAtlas.createText('VISIT CONFIRMED', {
    fontSize: 0.08,
    color: accent,
    align: 'center',
    letterSpacingPx: 1.5,
  });
  statusLabel.position.set(0, -0.08, 0.02);
  confirmPanel.add(statusLabel);

  root.add(confirmPanel);

  // Handlers
  function showConfirmPanel(payload) {
    const slot = payload?.slot || payload?.slotIso || payload || '';
    const text = String(slot);
    if (slotLabel && slotLabel.parent) {
      slotLabel.removeFromParent();
    }
    const newSlotLabel = ctx.fontAtlas.createText(text, {
      fontSize: 0.12,
      color: surface,
      align: 'center',
    });
    newSlotLabel.position.set(0, 0.08, 0.02);
    confirmPanel.add(newSlotLabel);

    confirmPanel.visible = true;

    const tl = gsap.timeline();
    tl.to(confirmPanel.scale, { x: 1, y: 1, z: 1, duration: 0.5, ease: 'back.out(1.7)' });
    tl.fromTo(confirmPanel.position, { y: -0.75 }, { y: -0.6, duration: 0.5, ease: 'power2.out' }, 0);
    timelines.push(tl);
  }

  function hideConfirmPanel() {
    if (!confirmPanel.visible) return;
    const tl = gsap.timeline({
      onComplete: () => { confirmPanel.visible = false; },
    });
    tl.to(confirmPanel.scale, { x: 0, y: 0, z: 0, duration: 0.25, ease: 'power2.in' });
    timelines.push(tl);
  }

  root.userData.handlers = {
    hover: () => {
      const tl = gsap.timeline();
      tl.to(root.position, { y: 0.15, duration: 0.35, ease: 'power2.out' });
      timelines.push(tl);
    },
    unhover: () => {
      const tl = gsap.timeline();
      tl.to(root.position, { y: 0, duration: 0.35, ease: 'power2.out' });
      timelines.push(tl);
    },
    click: () => {
      const tl = gsap.timeline();
      tl.to(root.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' })
        .to(root.scale, { x: 1, y: 1, z: 1, duration: 0.2, ease: 'power2.out' });
      timelines.push(tl);
      ctx.emit('hub-home.select', { source: config.id, node: root.name });
    },
    focus: () => {
      edge.visible = true;
      const tl = gsap.timeline();
      tl.to(edgeMat, { opacity: 0.45, duration: 0.2, ease: 'power2.out' });
      timelines.push(tl);
    },
    blur: () => {
      const tl = gsap.timeline({ onComplete: () => { edge.visible = false; } });
      tl.to(edgeMat, { opacity: 0, duration: 0.2, ease: 'power2.in' });
      timelines.push(tl);
    },
    confirmPanel: (payload) => {
      if (payload?.confirmed === false || payload?.ok === false) {
        hideConfirmPanel();
      } else {
        showConfirmPanel(payload);
      }
    },
  };

  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    root.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m.dispose());
        } else {
          obj.material.dispose();
        }
      }
    });
    disposables.forEach((d) => { try { d.dispose(); } catch {} });
  };

  return root;
}
